function getStreak(habit) {
  let count = 0
  const cursor = new Date()
  for (let i = 0; i < 365; i++) {
    const date = dateKey(cursor)
    const kept = habit.type === 'bad'
      ? date >= (habit.stoppedAt || habit.createdAt) && habit.history?.[date] !== false
      : !!habit.history?.[date]
    if (!kept) break
    count++
    cursor.setDate(cursor.getDate() - 1)
  }
  return count
}

function App() {
  const [habits, setHabits] = useState(() => JSON.parse(localStorage.getItem('steady-habits')) || initialHabits)
  const [expenses, setExpenses] = useState(() => { const saved = JSON.parse(localStorage.getItem('levelup-expenses') || '[]'); return saved.length ? saved : initialExpenses })
  const [paymentModes, setPaymentModes] = useState(() => Array.from(new Set([...defaultPaymentModes, ...JSON.parse(localStorage.getItem('levelup-payment-modes') || '[]')])))
  const [expenseForm, setExpenseForm] = useState({ description: '', amount: '', paymentMode: '', date: today })
  const [editingExpense, setEditingExpense] = useState(null)
  const [bulkExpenses, setBulkExpenses] = useState([])
  const [expenseMonth, setExpenseMonth] = useState('all')
  const [expenseYear, setExpenseYear] = useState('all')
  const [expenseStart, setExpenseStart] = useState('')
  const [expenseEnd, setExpenseEnd] = useState('')
  const [page, setPage] = useState('dashboard')
  const [filter, setFilter] = useState('all')
  const [editing, setEditing] = useState(null)
  const [menuOpen, setMenuOpen] = useState(null)
  const [form, setForm] = useState({ name: '', note: '', target: '', type: 'good', color: '#4fa3ff', stoppedAt: today })
  const [user, setUser] = useState(null)
  const [cloudLoaded, setCloudLoaded] = useState(!firebaseReady)
  const [authChecked, setAuthChecked] = useState(!firebaseReady)
  const [authError, setAuthError] = useState('')
  const firstName = user?.displayName?.trim().split(/\s+/)[0]
  const appName = firstName ? `${firstName} Level Up` : 'LevelUp'

  useEffect(() => localStorage.setItem('steady-habits', JSON.stringify(habits)), [habits])
  useEffect(() => localStorage.setItem('levelup-expenses', JSON.stringify(expenses)), [expenses])
  useEffect(() => localStorage.setItem('levelup-payment-modes', JSON.stringify(paymentModes)), [paymentModes])
  useEffect(() => {
    if (!firebaseReady) return
    return onAuthStateChanged(auth, currentUser => {
      setUser(currentUser)
      setCloudLoaded(!currentUser)
      setAuthChecked(true)
      setAuthError('')
    })
  }, [])
  useEffect(() => {
    if (!user) return
    const habitsRef = doc(db, 'users', user.uid, 'habits', 'data')
    return onSnapshot(habitsRef, snapshot => {
      if (snapshot.exists()) {
        const data = snapshot.data()
        setHabits(data.items || [])
        if (data.expenses?.length) setExpenses(data.expenses)
        if (data.paymentModes) setPaymentModes(data.paymentModes)
      } else setDoc(habitsRef, { items: habits, expenses, paymentModes })
      setCloudLoaded(true)
    }, () => { setAuthError('Could not connect to your cloud habits.'); setCloudLoaded(true) })
  }, [user])
  useEffect(() => {
    if (!user || !cloudLoaded) return
    setDoc(doc(db, 'users', user.uid, 'habits', 'data'), { items: habits, expenses, paymentModes }).catch(() => setAuthError('Your latest change could not be synced.'))
  }, [habits, expenses, paymentModes, user, cloudLoaded])

  const stats = useMemo(() => {
    const done = habits.filter(h => h.type === 'bad' ? h.history?.[today] !== false : h.history?.[today]).length
    const best = Math.max(0, ...habits.map(getStreak))
    return { done, total: habits.length, best }
  }, [habits])

  const goAdd = () => { setEditing(null); setForm({ name: '', note: '', target: '', type: 'good', color: '#4fa3ff', stoppedAt: today }); setPage('add') }
  const goEdit = (habit) => { setEditing(habit.id); setForm({ name: habit.name, note: habit.note, target: habit.target || '', type: habit.type, color: habit.color, stoppedAt: habit.stoppedAt || habit.createdAt }); setMenuOpen(null); setPage('add') }
  const toggleDate = (id, date = today) => setHabits(items => items.map(h => {
    if (h.id !== id) return h
    const completed = h.type === 'bad' ? date >= (h.stoppedAt || h.createdAt) && h.history?.[date] !== false : !!h.history?.[date]
    return { ...h, history: { ...h.history, [date]: !completed } }
  }))
  const toggle = (id) => toggleDate(id)
  const deleteHabit = (id) => { setHabits(items => items.filter(h => h.id !== id)); setMenuOpen(null) }
  const save = (e) => {
    e.preventDefault()
    if (!form.name.trim()) return
    if (editing) setHabits(items => items.map(h => h.id === editing ? { ...h, ...form } : h))
    else setHabits(items => [...items, { ...form, id: Date.now(), history: {}, createdAt: today }])
    setPage('habits')
  }
  const shownHabits = habits.filter(h => filter === 'all' || h.type === filter)
  const expenseMonths = [...new Set(expenses.map(item => item.date.slice(0, 7)))].sort().reverse()
  const expenseYears = [...new Set(expenses.map(item => item.date.slice(0, 4)))].sort().reverse()
  const filteredExpenses = expenses.filter(item => (expenseMonth === 'all' || item.date.startsWith(expenseMonth)) && (expenseYear === 'all' || item.date.startsWith(expenseYear)) && (!expenseStart || item.date >= expenseStart) && (!expenseEnd || item.date <= expenseEnd))
  const addExpense = (event) => {
    event.preventDefault()
    if (!expenseForm.description.trim() || !expenseForm.amount || !expenseForm.paymentMode) return
    if (editingExpense) setExpenses(items => items.map(item => item.id === editingExpense ? { ...expenseForm, amount: Number(expenseForm.amount), id: item.id } : item))
    else setExpenses(items => [{ ...expenseForm, amount: Number(expenseForm.amount), id: Date.now() }, ...items])
    setEditingExpense(null)
    setExpenseForm({ description: '', amount: '', paymentMode: paymentModes[0] || '', date: today })
    setPage('expenses')
  }
  const goExpenseAdd = () => { setEditingExpense(null); setExpenseForm({ description: '', amount: '', paymentMode: paymentModes[0] || '', date: today }); setPage('expense-add') }
  const goExpenseEdit = expense => { setEditingExpense(expense.id); setExpenseForm({ description: expense.description, amount: String(expense.amount), paymentMode: expense.paymentMode, date: expense.date }); setPage('expense-add') }
  const goBulkAdd = () => { setBulkExpenses([{ description: '', amount: '', paymentMode: paymentModes[0] || '', date: today }]); setPage('expense-bulk') }
  const saveBulkExpenses = event => { event.preventDefault(); const valid = bulkExpenses.filter(item => item.description.trim() && item.amount && item.paymentMode); if (!valid.length) return; setExpenses(items => [...valid.map((item, index) => ({ ...item, amount: Number(item.amount), id: Date.now() + index })), ...items]); setPage('expenses') }

  if (firebaseReady && !authChecked) return <div className="auth-loading">Loading your space…</div>
  if (firebaseReady && !user) return <LoginPage error={authError} onLogin={() => signInWithPopup(auth, googleProvider).catch(() => setAuthError('Sign-in was cancelled or could not be completed. Please try again.'))} />

  return <div className="app-shell">
    <aside className="sidebar">
      <button className="brand" onClick={() => setPage('dashboard')}><span className="brand-mark">L</span><span>{appName}</span></button>
      <nav>
        <p className="nav-group">HABIT MANAGER</p>
        <Nav item="dashboard" label="Overview" page={page} setPage={setPage} />
        <Nav item="habits" label="My habits" page={page} setPage={setPage} />
        <Nav item="stats" label="Stats" page={page} setPage={setPage} />
        <Nav item="history" label="History" page={page} setPage={setPage} />
        <p className="nav-group">EXPENSE MANAGER</p>
        <Nav item="expenses" label="Expenses" page={page} setPage={setPage} />
        <Nav item="history" label="Expense history" page={page} setPage={setPage} expense />
        <Nav item="stats" label="Expense stats" page={page} setPage={setPage} expense />
        <Nav item="payments" label="Payment modes" page={page} setPage={setPage} />
      </nav>
      <div className="sidebar-bottom"><Nav item="settings" label="Settings" page={page} setPage={setPage} /><Profile user={user} /></div>
    </aside>
    <main>
      <header className="topbar"><button className="mobile-logo brand" onClick={() => setPage('dashboard')}><span className="brand-mark">L</span><span>{appName}</span></button><div className="today">{dateLabel}</div><div className="header-actions"><CloudStatus user={user} error={authError} /><button className="add-button" onClick={page.startsWith('expense') || page === 'expenses' || page === 'payments' ? goExpenseAdd : goAdd}><b>+</b> Add {page.startsWith('expense') || page === 'expenses' || page === 'payments' ? 'expense' : 'habit'}</button></div></header>
      {page === 'dashboard' && <Dashboard habits={habits} stats={stats} onToggle={toggle} onToggleDate={toggleDate} onAdd={goAdd} onEdit={goEdit} menuOpen={menuOpen} setMenuOpen={setMenuOpen} onDelete={deleteHabit} />}
      {page === 'habits' && <Habits habits={shownHabits} filter={filter} setFilter={setFilter} onToggle={toggle} onAdd={goAdd} onEdit={goEdit} menuOpen={menuOpen} setMenuOpen={setMenuOpen} onDelete={deleteHabit} />}
      {page === 'add' && <HabitForm form={form} setForm={setForm} onSave={save} onCancel={() => setPage('habits')} editing={!!editing} />}
      {page === 'stats' && <Stats habits={habits} />}
      {page === 'expenses' && <Expenses expenses={filteredExpenses} filters={{ month: expenseMonth, setMonth: setExpenseMonth, months: expenseMonths, year: expenseYear, setYear: setExpenseYear, years: expenseYears, start: expenseStart, setStart: setExpenseStart, end: expenseEnd, setEnd: setExpenseEnd }} onAdd={goExpenseAdd} onBulkAdd={goBulkAdd} onEdit={goExpenseEdit} onDelete={id => setExpenses(items => items.filter(item => item.id !== id))} />}
      {page === 'expense-add' && <ExpenseForm form={expenseForm} setForm={setExpenseForm} paymentModes={paymentModes} onSave={addExpense} onCancel={() => setPage('expenses')} editing={!!editingExpense} />}
      {page === 'expense-bulk' && <BulkExpenseForm rows={bulkExpenses} setRows={setBulkExpenses} paymentModes={paymentModes} onSave={saveBulkExpenses} onCancel={() => setPage('expenses')} />}
      {page === 'expense-stats' && <ExpenseStats expenses={filteredExpenses} allExpenses={expenses} filters={{ month: expenseMonth, setMonth: setExpenseMonth, months: expenseMonths, year: expenseYear, setYear: setExpenseYear, years: expenseYears, start: expenseStart, setStart: setExpenseStart, end: expenseEnd, setEnd: setExpenseEnd }} />}
      {page === 'expense-history' && <ExpenseHistory expenses={filteredExpenses} filters={{ month: expenseMonth, setMonth: setExpenseMonth, months: expenseMonths, year: expenseYear, setYear: setExpenseYear, years: expenseYears, start: expenseStart, setStart: setExpenseStart, end: expenseEnd, setEnd: setExpenseEnd }} />}
      {page === 'payments' && <PaymentModes modes={paymentModes} setModes={setPaymentModes} />}
      {page === 'history' && <History habits={habits} />}
      {page === 'settings' && <section className="page simple-page"><p className="eyebrow">PREFERENCES</p><h1>Settings</h1><p>Your habits are stored securely in this browser.</p></section>}
      <footer className="site-footer">Conceptualized and developed by <a href="https://www.linkedin.com/in/pulkit-singh-80a66917a/" target="_blank" rel="noreferrer">Pulkit Singh <span aria-hidden="true">↗</span></a></footer>
    </main>
    <MobileNav page={page} setPage={setPage} user={user} onLogout={() => signOut(auth)} />
    <button className="floating-add" onClick={page.startsWith('expense') || page === 'expenses' || page === 'payments' ? goExpenseAdd : goAdd}>+</button>
  </div>
}

function CloudStatus({ user, error }) {
  if (!firebaseReady) return <span className="cloud-status local">Local only</span>
  if (user) return <button className="account-button" title="Sign out" onClick={() => signOut(auth)}>{user.photoURL ? <img src={user.photoURL} alt="" /> : null}<span>Log out</span></button>
  return null
}

function LoginPage({ onLogin, error }) {
  return <main className="login-page"><section className="login-panel"><button className="brand login-brand"><span className="brand-mark">L</span><span>LevelUp</span></button><div className="login-copy"><p className="eyebrow">YOUR PERSONAL RITUAL SPACE</p><h1>Small steps,<br /><em>every day.</em></h1><p>Build a life you’re proud of, one deliberate choice at a time.</p></div><div className="login-feature"><span>✦</span><p>Your habits stay safely in sync across every device.</p></div></section><section className="login-form"><div className="login-card"><p className="eyebrow">WELCOME TO LEVELUP</p><h2>Make today count.</h2><p>Sign in to access your habits and keep your streak going wherever you are.</p><button className="google-login" onClick={onLogin}><b>G</b> Continue with Google</button>{error && <p className="login-error">{error}</p>}<small>By continuing, you agree to keep showing up for yourself.</small></div></section></main>
}

function Nav({ item, label, page, setPage, expense }) { const destination = expense ? (item === 'history' ? 'expense-history' : 'expense-stats') : item; return <button className={`nav-item ${page === destination ? 'active' : ''}`} onClick={() => setPage(destination)}><span>{icons[item]}</span>{label}</button> }
function MobileNav({ page, setPage, user, onLogout }) {
  const expenseActive = page === 'expenses' || page.startsWith('expense') || page === 'payments'
  return <nav className="mobile-nav" aria-label="Main navigation">
    <button className={page === 'dashboard' ? 'active' : ''} onClick={() => setPage('dashboard')}><span>{icons.dashboard}</span>Overview</button>
    <button className={page === 'habits' || page === 'add' || page === 'history' || page === 'stats' ? 'active' : ''} onClick={() => setPage('habits')}><span>{icons.habits}</span>Habits</button>
    <button className={expenseActive ? 'active' : ''} onClick={() => setPage('expenses')}><span>{icons.expenses}</span>Expenses</button>
    {user && <button className="logout" onClick={onLogout}><span>↪</span>Log out</button>}
  </nav>
}
function Profile({ user }) { const name = user?.displayName || 'Your habit space'; const initial = name.charAt(0).toUpperCase(); return <div className="profile">{user?.photoURL ? <img className="avatar" src={user.photoURL} alt="" referrerPolicy="no-referrer" /> : <div className="avatar">{initial}</div>}<div><strong>{name}</strong><small>{user?.email || 'Make it count.'}</small></div><span>⌄</span></div> }

function Dashboard({ habits, stats, onToggle, onToggleDate, onAdd, onEdit, menuOpen, setMenuOpen, onDelete }) {
  return <section className="page"><div className="headline"><div><p className="eyebrow">TODAY'S FOCUS</p><h1>Small steps, <em>big change.</em></h1><p className="subcopy">Show up for yourself today. You’ve got this.</p></div><div className="day-progress"><div className="progress-ring" style={{ '--progress': `${stats.total ? (stats.done / stats.total) * 100 : 0}%` }}><span>{stats.done}<small>/{stats.total}</small></span></div><p>habits completed</p></div></div>
    <section className="stat-grid"><Stat value={`${stats.done}/${stats.total}`} label="Completed today" icon="✓" /><Stat value={stats.best} label="Current best streak" icon="♨" /><Stat value={habits.length} label="Active habits" icon="◌" /></section>
    <WeekTracker habits={habits} onToggleDate={onToggleDate} onAdd={onAdd} onEdit={onEdit} onDelete={onDelete} />
  </section>
}
function Stat({ value, label, icon }) { return <article className="stat-card"><span className="stat-icon">{icon}</span><strong>{value}</strong><p>{label}</p></article> }
function HabitSection({ label, title, description, habits, accent, onToggle, onAdd, onEdit, menuOpen, setMenuOpen, onDelete }) { return <section className="habit-section"><div className="section-heading"><div><p className={`eyebrow ${accent}`}>{label}</p><h2>{title}</h2><p>{description}</p></div><button className="text-button" onClick={onAdd}>+ Add</button></div><div className="habit-list">{habits.length ? habits.map(h => <HabitCard key={h.id} habit={h} onToggle={onToggle} onEdit={onEdit} onDelete={onDelete} menuOpen={menuOpen} setMenuOpen={setMenuOpen} />) : <Empty onAdd={onAdd} />}</div></section> }
function WeekTracker({ habits, onToggleDate, onAdd, onEdit, onDelete }) { return <section className="week-tracker"><div className="section-heading"><div><p className="eyebrow">WEEKLY TRACKER</p><h2>Your habit rhythm</h2><p>Today comes first. Upcoming days are locked until they arrive.</p></div><button className="text-button" onClick={onAdd}>+ Add habit</button></div><div className="tracker-scroll"><div className="tracker-table"><div className="tracker-header"><div>HABIT</div>{weekDays.map(day => <div key={day.key} className={day.key === today ? 'is-today' : ''}><span>{day.weekday}</span><b>{day.day}</b></div>)}<div></div></div>{habits.map(habit => <div className="tracker-row" key={habit.id}><div className="tracker-habit"><i style={{ background: habit.color }}></i><div><strong>{habit.name}</strong><small>{habit.type === 'bad' ? `Stopped ${new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(new Date(`${habit.stoppedAt || habit.createdAt}T00:00:00`))}` : habit.target || habit.note || 'Daily habit'}</small></div></div>{weekDays.map(day => { const available = day.key <= today && (habit.type !== 'bad' || day.key >= (habit.stoppedAt || habit.createdAt)); const checked = habit.type === 'bad' ? available && habit.history?.[day.key] !== false : !!habit.history?.[day.key]; return <button key={day.key} disabled={!available} aria-label={`Toggle ${habit.name} for ${day.key}`} className={`day-check ${checked ? 'checked' : ''} ${habit.type}`} onClick={() => onToggleDate(habit.id, day.key)}>{checked ? '✓' : '×'}</button> })}<div className="tracker-menu"><button onClick={() => onEdit(habit)}>•••</button></div></div>)}{!habits.length && <Empty onAdd={onAdd} />}</div></div><p className="tracker-note"><span>✓</span> You can check or undo today and any past day. Future dates stay locked.</p></section> }
function HabitCard({ habit, onToggle, onEdit, onDelete, menuOpen, setMenuOpen }) { const completed = habit.type === 'bad' ? habit.history?.[today] !== false : !!habit.history?.[today], streak = getStreak(habit); return <article className={`habit-card ${completed ? 'completed' : ''}`}><button className="check" onClick={() => onToggle(habit.id)} aria-label={`Toggle ${habit.name}`}>{completed && '✓'}</button><div className="habit-color" style={{ background: habit.color }}></div><div className="habit-info"><h3>{habit.name}</h3><p>{habit.note || 'A small daily promise'}</p></div><div className="streak"><span>♨</span><strong>{streak}</strong><small>day streak</small></div><div className="card-actions"><button onClick={() => setMenuOpen(menuOpen === habit.id ? null : habit.id)}>{icons.more}</button>{menuOpen === habit.id && <div className="menu"><button onClick={() => onEdit(habit)}>Edit habit</button><button className="danger" onClick={() => onDelete(habit.id)}>Delete habit</button></div>}</div></article> }
function Empty({ onAdd }) { return <button className="empty" onClick={onAdd}>+ Add your first habit</button> }
function Habits({ habits, filter, setFilter, ...props }) { return <section className="page"><p className="eyebrow">YOUR ROUTINE</p><h1>My habits</h1><p className="subcopy">Manage the rituals that shape your days.</p><div className="filters"><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>All</button><button className={filter === 'good' ? 'selected' : ''} onClick={() => setFilter('good')}>Good habits</button><button className={filter === 'bad' ? 'selected' : ''} onClick={() => setFilter('bad')}>Bad habits</button></div><div className="habit-list full-list">{habits.length ? habits.map(h => <HabitCard key={h.id} habit={h} {...props} />) : <Empty onAdd={props.onAdd} />}</div></section> }
function HabitForm({ form, setForm, onSave, onCancel, editing }) { return <section className="page form-page"><p className="eyebrow">{editing ? 'REFINE YOUR ROUTINE' : 'START SOMETHING NEW'}</p><h1>{editing ? 'Edit habit' : 'Create a habit'}</h1><p className="subcopy">Keep it clear, small and easy to show up for.</p><form onSubmit={onSave}><label>Habit name<input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="e.g. Drink a glass of water" autoFocus /></label><label>A gentle reminder <input value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} placeholder="What does success look like?" /></label><label>Target group<select value={form.target} onChange={e => setForm({ ...form, target: e.target.value })}><option value="">Choose what this habit supports</option>{targetGroups.map(group => <option key={group} value={group}>{group}</option>)}</select><small>Use groups to see where your effort is going on the Stats page.</small></label><fieldset><legend>What kind of habit is this?</legend><div className="type-options"><button type="button" className={form.type === 'good' ? 'type-selected good-type' : ''} onClick={() => setForm({ ...form, type: 'good', color: '#4fa3ff' })}><span>✦</span><b>Good habit</b><small>Build a routine by checking it off.</small></button><button type="button" className={form.type === 'bad' ? 'type-selected bad-type' : ''} onClick={() => setForm({ ...form, type: 'bad', color: '#ffac7d', stoppedAt: form.stoppedAt || today })}><span>◌</span><b>Bad habit</b><small>Stay clear of it to protect your streak.</small></button></div></fieldset>{form.type === 'bad' && <label className="stop-date">When did you stop?<input type="date" max={today} value={form.stoppedAt} onChange={e => setForm({ ...form, stoppedAt: e.target.value })} required /><small>Your clean streak starts from this date.</small></label>}<div className="form-actions"><button type="button" className="cancel" onClick={onCancel}>Cancel</button><button className="save" type="submit">{editing ? 'Save changes' : 'Create habit'} →</button></div></form></section> }
function ExpenseForm({ form, setForm, paymentModes, onSave, onCancel, editing }) { return <section className="page form-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>{editing ? 'Edit' : 'Add an'} <em>expense.</em></h1><p className="subcopy">Record every payment in one simple place.</p><form onSubmit={onSave}><label>Expense<input value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="e.g. Tea and refreshments" autoFocus /></label><label>Amount<input type="number" min="0" step="0.01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="0.00" /></label><label>Payment mode<select value={form.paymentMode} onChange={e => setForm({ ...form, paymentMode: e.target.value })} required><option value="">Choose payment mode</option>{paymentModes.map(mode => <option key={mode}>{mode}</option>)}</select></label><label>Date<input type="date" value={form.date} max={today} onChange={e => setForm({ ...form, date: e.target.value })} /></label><div className="form-actions"><button type="button" className="cancel" onClick={onCancel}>Cancel</button><button className="save" type="submit">{editing ? 'Save changes' : 'Save expense'} →</button></div></form></section> }
function BulkExpenseForm({ rows, setRows, paymentModes, onSave, onCancel }) { const update = (index, field, value) => setRows(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, [field]: value } : item)); const addRow = () => setRows(items => [...items, { description: '', amount: '', paymentMode: paymentModes[0] || '', date: today }]); return <section className="page bulk-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Add multiple <em>expenses.</em></h1><p className="subcopy">Enter several payments at once, then save them together.</p><form onSubmit={onSave}><div className="bulk-table"><div className="bulk-header"><span>Expense</span><span>Amount</span><span>Payment mode</span><span>Date</span><span></span></div>{rows.map((row, index) => <div className="bulk-row" key={index}><input value={row.description} onChange={e => update(index, 'description', e.target.value)} placeholder="Expense" /><input type="number" min="0" step="0.01" value={row.amount} onChange={e => update(index, 'amount', e.target.value)} placeholder="0.00" /><select value={row.paymentMode} onChange={e => update(index, 'paymentMode', e.target.value)}><option value="">Choose</option>{paymentModes.map(mode => <option key={mode}>{mode}</option>)}</select><input type="date" value={row.date} max={today} onChange={e => update(index, 'date', e.target.value)} /><button type="button" onClick={() => setRows(items => items.filter((_, itemIndex) => itemIndex !== index))} disabled={rows.length === 1}>×</button></div>)}</div><button type="button" className="text-button" onClick={addRow}>+ Add another row</button><div className="form-actions"><button type="button" className="cancel" onClick={onCancel}>Cancel</button><button className="save" type="submit">Save all expenses →</button></div></form></section> }
function ExpenseFilters({ filters }) { return <div className="expense-filters"><label>Month<select value={filters.month} onChange={e => filters.setMonth(e.target.value)}><option value="all">All months</option>{filters.months.map(value => <option key={value} value={value}>{new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(new Date(`${value}-01T00:00:00`))}</option>)}</select></label><label>Year<select value={filters.year} onChange={e => filters.setYear(e.target.value)}><option value="all">All years</option>{filters.years.map(year => <option key={year}>{year}</option>)}</select></label><label>From<input type="date" value={filters.start} onChange={e => filters.setStart(e.target.value)} /></label><label>To<input type="date" value={filters.end} onChange={e => filters.setEnd(e.target.value)} /></label><button type="button" onClick={() => { filters.setMonth('all'); filters.setYear('all'); filters.setStart(''); filters.setEnd('') }}>Clear</button></div> }
function ExpenseDateCard({ date, items, onEdit, onDelete }) { const [open, setOpen] = useState(false); const total = items.reduce((sum, item) => sum + item.amount, 0); const confirmDelete = item => { if (window.confirm(`Delete “${item.description}” (₹${item.amount})? This cannot be undone.`)) onDelete(item.id) }; return <section className={`expense-date ${open ? 'open' : ''}`}><button className="expense-date-heading" onClick={() => setOpen(!open)} aria-expanded={open}><div><span className="date-arrow">{open ? '⌄' : '›'}</span><h2>{new Intl.DateTimeFormat('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(`${date}T00:00:00`))}</h2></div><span><b>₹{total.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</b><small>{items.length} expense{items.length === 1 ? '' : 's'}</small></span></button>{open && items.map(item => <article className="expense-row" key={item.id}><div><strong>{item.description}</strong><small>{item.paymentMode}</small></div><b>₹{item.amount.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</b><div className="expense-row-actions"><button onClick={() => onEdit(item)}>Edit</button><button className="delete-expense" onClick={() => confirmDelete(item)}>Delete</button></div></article>)}</section> }
function Expenses({ expenses, filters, onAdd, onBulkAdd, onEdit, onDelete }) { const total = expenses.reduce((sum, item) => sum + item.amount, 0); const groups = expenses.reduce((all, item) => { (all[item.date] ||= []).push(item); return all }, {}); return <section className="page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Your <em>spending.</em></h1><p className="subcopy">{expenses.length} entries · ₹{total.toLocaleString('en-IN', { maximumFractionDigits: 2 })} recorded</p><div className="expense-actions"><button className="text-button" onClick={onBulkAdd}>+ Add multiple expenses</button></div><ExpenseFilters filters={filters} /><div className="expense-list date-sections">{Object.entries(groups).sort(([a], [b]) => b.localeCompare(a)).map(([date, items]) => <ExpenseDateCard key={date} date={date} items={items} onEdit={onEdit} onDelete={onDelete} />)}{!expenses.length && <button className="empty" onClick={onAdd}>+ Add your first expense</button>}</div></section> }
function ExpenseStats({ expenses, filters }) { const total = expenses.reduce((sum, item) => sum + item.amount, 0); const byMode = Object.values(expenses.reduce((all, item) => { all[item.paymentMode] = all[item.paymentMode] || { name: item.paymentMode, total: 0 }; all[item.paymentMode].total += item.amount; return all }, {})).sort((a, b) => b.total - a.total); return <section className="page stats-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Expense <em>stats.</em></h1><p className="subcopy">Your recorded spending, broken down by payment mode.</p><ExpenseFilters filters={filters} /><div className="stats-summary"><Stat value={`₹${total.toLocaleString('en-IN', { maximumFractionDigits: 0 })}`} label="Total spending" icon="₹" /><Stat value={expenses.length} label="Transactions" icon="▣" /><Stat value={byMode[0]?.name || '—'} label="Most used payment mode" icon="◌" /></div><section className="stats-panel"><div className="section-heading"><div><p className="eyebrow">PAYMENT BREAKDOWN</p><h2>Where you paid</h2></div></div><div className="group-progress">{byMode.length ? byMode.map((mode, index) => { const percent = total ? Math.round(mode.total / total * 100) : 0; return <article key={mode.name}><div><span style={{ background: index % 2 ? '#72b7ff' : '#4fa3ff' }}></span><strong>{mode.name}</strong><b>₹{mode.total.toLocaleString('en-IN', { maximumFractionDigits: 0 })}</b></div><div className="group-track"><i style={{ width: `${percent}%`, background: index % 2 ? '#72b7ff' : '#4fa3ff' }} /></div><small>{percent}% of recorded spending</small></article> }) : <p className="no-stats">No expenses match these filters.</p>}</div></section></section> }
function ExpenseHistory({ expenses, filters }) { const groups = expenses.reduce((all, item) => { const key = item.date.slice(0, 7); (all[key] ||= []).push(item); return all }, {}); return <section className="page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Expense <em>history.</em></h1><p className="subcopy">Your spending, grouped month by month.</p><ExpenseFilters filters={filters} /><div className="expense-history">{Object.entries(groups).sort(([a], [b]) => b.localeCompare(a)).map(([key, items]) => <section key={key} className="history-month"><div><h2>{new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(new Date(`${key}-01T00:00:00`))}</h2><b>₹{items.reduce((sum, item) => sum + item.amount, 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</b></div><p>{items.length} transactions</p></section>)}{!Object.keys(groups).length && <p className="no-stats">No expenses match these filters.</p>}</div></section> }
function PaymentModes({ modes, setModes }) { const [newMode, setNewMode] = useState(''); const [dragged, setDragged] = useState(null); const add = event => { event.preventDefault(); const value = newMode.trim(); if (value && !modes.includes(value)) { setModes([...modes, value]); setNewMode('') } }; const move = target => { if (!dragged || dragged === target) return; const next = modes.filter(mode => mode !== dragged); next.splice(next.indexOf(target), 0, dragged); setModes(next); setDragged(null) }; return <section className="page payment-page"><p className="eyebrow">EXPENSE MANAGER</p><h1>Payment <em>modes.</em></h1><p className="subcopy">Drag modes to set the order shown when adding an expense.</p><form className="mode-form" onSubmit={add}><input value={newMode} onChange={e => setNewMode(e.target.value)} placeholder="e.g. ICICI UPI" /><button className="save">Add mode</button></form><div className="mode-list">{modes.map(mode => <div key={mode} draggable onDragStart={() => setDragged(mode)} onDragOver={event => event.preventDefault()} onDrop={() => move(mode)} className={dragged === mode ? 'dragging' : ''}><span><i>⠿</i>{mode}</span><button onClick={() => setModes(modes.filter(item => item !== mode))} aria-label={`Delete ${mode}`}>×</button></div>)}</div></section> }
function History({ habits }) { return <section className="page"><p className="eyebrow">LOOKING BACK</p><h1>History</h1><p className="subcopy">A simple record of your consistency.</p><div className="history-grid">{habits.map(h => <article className="history-card" key={h.id}><span style={{ background: h.color }}></span><div><h3>{h.name}</h3><p>{h.type === 'good' ? 'Good habit' : 'Bad habit'}</p></div><strong>{getStreak(h)}<small> day streak</small></strong></article>)}</div></section> }

function Stats({ habits }) {
  const days = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (6 - index)); return dateKey(date) })
  const isComplete = (habit, date) => habit.type === 'bad'
    ? date >= (habit.stoppedAt || habit.createdAt) && habit.history?.[date] !== false
    : !!habit.history?.[date]
  const daily = days.map(date => { const eligible = habits.filter(h => h.type !== 'bad' || date >= (h.stoppedAt || h.createdAt)); const done = eligible.filter(h => isComplete(h, date)).length; return { date, done, total: eligible.length, percent: eligible.length ? Math.round(done / eligible.length * 100) : 0 } })
  const completed = daily.reduce((sum, day) => sum + day.done, 0)
  const possible = daily.reduce((sum, day) => sum + day.total, 0)
  const consistency = possible ? Math.round(completed / possible * 100) : 0
  const bestDay = [...daily].sort((a, b) => b.percent - a.percent)[0]
  const groups = Object.values(habits.reduce((all, habit) => { const name = habit.target || 'Unassigned'; if (!all[name]) all[name] = { name, done: 0, total: 0, color: habit.color }; days.forEach(date => { if (habit.type !== 'bad' || date >= (habit.stoppedAt || habit.createdAt)) { all[name].total++; if (isComplete(habit, date)) all[name].done++ } }); return all }, {})).sort((a, b) => b.done / Math.max(b.total, 1) - a.done / Math.max(a.total, 1))
  return <section className="page stats-page">
    <p className="eyebrow">YOUR PROGRESS</p><h1>Stats that tell your <em>story.</em></h1><p className="subcopy">A look at your consistency over the last seven days.</p>
    <div className="stats-summary"><Stat value={`${consistency}%`} label="Weekly consistency" icon="◔" /><Stat value={completed} label="Habits completed" icon="✓" /><Stat value={bestDay ? `${bestDay.percent}%` : '—'} label="Best day" icon="✦" /></div>
    <section className="stats-panel"><div className="section-heading"><div><p className="eyebrow">LAST 7 DAYS</p><h2>Daily rhythm</h2></div><strong>{completed}<small> completions</small></strong></div><div className="bar-chart">{daily.map(day => <div className="bar-column" key={day.date}><div className="bar-track"><div className="bar-fill" style={{ height: `${day.percent}%` }} title={`${day.done}/${day.total} completed`} /></div><b>{day.percent}%</b><small>{new Intl.DateTimeFormat('en-US', { weekday: 'short' }).format(new Date(`${day.date}T00:00:00`))}</small></div>)}</div></section>
    <section className="stats-panel"><div className="section-heading"><div><p className="eyebrow">BY TARGET GROUP</p><h2>Where you’re growing</h2><p>Completion rate for each focus area this week.</p></div></div><div className="group-progress">{groups.length ? groups.map(group => {
      const percent = group.total ? Math.round(group.done / group.total * 100) : 0
      return <article key={group.name}><div><span style={{ background: group.color }}></span><strong>{group.name}</strong><b>{percent}%</b></div><div className="group-track"><i style={{ width: `${percent}%`, background: group.color }} /></div><small>{group.done} of {group.total} check-ins completed</small></article>
    }) : <p className="no-stats">Add a habit to start seeing your progress here.</p>}</div></section>
  </section>
}

export default App
